        turn = 0.75 if angle > 0 else -0.75
        return (-turn, turn)

    steer = angle / 70 - me.turn_rate / 240
    steer = max(-0.9, min(0.9, steer))

    if distance > 3.0:
        throttle = 0.95
    elif distance > 1.6:
        throttle = 0.8
    else:
        throttle = 0.62

    if abs(angle) > 65:
        throttle = min(throttle, 0.25)
